parameters.jsCode:
// Merge Webhook data + Partner ID + STRICT Intent from AI Engine
const wb = $('Webhook').first().json.body || $('Webhook').first().json;
let newPartnerId = null;
try {
  if ($('Créer Contact Client (res.partner)').isExecuted) {
    newPartnerId = $('Créer Contact Client (res.partner)').first()?.json?.result;
  }
} catch (e) {
  newPartnerId = null;
}

const partnerId = wb.partner_id || newPartnerId || false;
const callerName = wb.caller_name || "Client";
const callerPhone = wb.caller_phone || "";
const motif = wb.motif || "Demande";
const transcript = wb.transcript || "";

// Format clean phone for WhatsApp
let cleanPhone = callerPhone.replace(/\D/g, '');
if (cleanPhone.startsWith('0') && cleanPhone.length === 10) {
  cleanPhone = '212' + cleanPhone.substring(1);
} else if (cleanPhone.startsWith('2120')) {
  cleanPhone = '212' + cleanPhone.substring(4);
}
if (!cleanPhone) cleanPhone = "212694992392";

// 1. STRICT INTENT ENFORCEMENT : Use strictly what the Voice AI Engine decided
// DO NOT do regex / keyword search on transcript to avoid false positives!
let intentType = wb.intent_type || "general_inquiry";

// Only allow quote_request if items were actually specified and revenue > 0
if (intentType === "quote_request" && (!wb.items || wb.items.length === 0) && (!wb.expected_revenue || wb.expected_revenue === 0)) {
  intentType = "general_inquiry";
}

// 2. Extract Quantity & Product Lines (ONLY for genuine quote_request)
let qty = 1;
let matchedProdId = 181;
let unitPrice = 0;
let expectedRevenue = 0;

if (intentType === "quote_request") {
  if (Array.isArray(wb.items) && wb.items.length > 0) {
    const firstItem = wb.items[0];
    qty = firstItem.quantity || 1;
    unitPrice = firstItem.unit_price || 0;
    expectedRevenue = wb.expected_revenue || (unitPrice * qty);
  } else {
    expectedRevenue = Number(wb.expected_revenue) || 1500;
  }
}

let leadTitlePrefix = "[IA INFO] ";
if (intentType === "order_cancellation") leadTitlePrefix = "[IA ANNULATION] ";
else if (intentType === "support_urgent") leadTitlePrefix = "[IA URGENCE] ";
else if (intentType === "quote_request") leadTitlePrefix = "[IA DEVIS] ";

// Prepare clean WhatsApp message body
let messageText = `Bonjour Mr. ${callerName} 👋,\n\nNous vous remercions sincèrement d'avoir contacté IT Mall ! 🏢\n\n📋 Votre demande d'information : ${motif}\n\n👨‍💼 Un conseiller commercial étudie votre besoin et vous recontacte très rapidement.\n\nToute l'équipe d'IT Mall vous remercie chaleureusement pour votre confiance et reste à votre entière disposition.`;

if (intentType === "order_cancellation") {
  messageText = `Bonjour Mr. ${callerName} 👋,\n\nNous vous remercions d'avoir contacté IT Mall ! 🏢\n\n❌ Votre demande d'annulation a bien été prise en compte :\n📋 Motif : ${motif}\n\n👨‍💼 Notre service client traite votre dossier dans les meilleurs délais.\n\nToute l'équipe d'IT Mall reste à votre entière disposition.`;
} else if (intentType === "quote_request") {
  messageText = `Bonjour Mr. ${callerName} 👋,\n\nNous vous remercions chaleureusement d'avoir fait appel à IT Mall ! 🏢\n\n📄 Votre devis officiel a bien été généré suite à votre appel.\n📋 Objet : ${motif}\n\n👨‍💼 Tous les détails chiffrés sont consultables dans votre devis en pièce jointe.\n\nToute l'équipe d'IT Mall vous remercie chaleureusement pour votre confiance et se tient à votre entière disposition !`;
} else if (intentType === "support_urgent") {
  messageText = `Bonjour Mr. ${callerName} 👋,\n\nNous vous remercions d'avoir contacté le Support IT Mall ! 🏢\n\n🚨 Signalement urgent bien enregistré : ${motif}\n\n👨‍🔧 Notre équipe technique a pris en charge votre demande en priorité absolue.\n\nToute l'équipe IT Mall reste mobilisée à vos côtés.`;
}

return [{
  json: {
    partner_id: partnerId,
    intent_type: intentType,
    motif: motif,
    caller_name: callerName,
    caller_phone: callerPhone,
    clean_phone: cleanPhone,
    message_text: messageText,
    transcript: transcript,
    priority: (intentType === "support_urgent" || intentType === "order_cancellation") ? "3" : "2",
    expected_revenue: expectedRevenue,
    lead_name: leadTitlePrefix + motif + " - " + callerName,
    product_id: matchedProdId,
    quantity: qty,
    unit_price: unitPrice
  }
}];

