const partnerId = $('Préparer Données Appel').first().json.partner_id || 101;
const oppId = $('Créer Opportunité CRM').first().json.result || false;
const searchRes = $('Chercher Produit Odoo').first().json.result;
const prepData = $('Préparer Données Appel').first().json;

let prodId = prepData.product_id;
let unitPrice = prepData.unit_price;

if (Array.isArray(searchRes) && searchRes.length > 0) {
  prodId = searchRes[0].id;
  unitPrice = searchRes[0].list_price;
}

const payload = {
  jsonrpc: "2.0",
  method: "call",
  params: {
    service: "object",
    method: "execute_kw",
    args: [
      $env.ODOO_DB || "it_mall_db",
      parseInt($env.ODOO_UID || "2"),
      $env.ODOO_PASS || "YOUR_ODOO_RPC_PASSWORD",
      "sale.order",
      "create",
      [
        {
          partner_id: partnerId,
          opportunity_id: oppId,
          order_line: [
            [0, 0, {
              product_id: prodId,
              product_uom_qty: prepData.quantity || 1,
              price_unit: unitPrice
            }]
          ]
        }
      ]
    ]
  },
  id: 2
};

return [{ json: { payload: payload } }];
